import 'dart:convert';
import 'dart:io';

const String _out = 'lib/rendering/webgl/generated_shaders.dart';
const String _dir = 'shaders/rendering';
const String _manifestPath = '$_dir/manifest.json';

final RegExp _includePattern = RegExp(r'^\s*#include\s+"([^"]+)"\s*$');

const String _header = '''
// GENERATED by tools/renderer/shaders.dart from shaders/rendering/**/*.vert,frag — do not edit.




''';

Map<String, String> _readManifest() {
  final file = File(_manifestPath);
  if (!file.existsSync()) {
    stderr.writeln('missing manifest: $_manifestPath');
    exit(1);
  }
  final decoded = jsonDecode(file.readAsStringSync()) as Map<String, dynamic>;
  final shaders = decoded['shaders'] as Map<String, dynamic>;
  return shaders.map((key, value) => MapEntry(key, value as String));
}

/// Resolves `#include "include/..."` directives recursively with cycle
/// detection (`[S3-0]`).
String resolveShaderIncludes(
  String source,
  String sourceRelPath, {
  String baseDir = _dir,
  Set<String>? activeStack,
}) {
  final stack = activeStack ?? <String>{sourceRelPath};
  final lines = source.replaceAll('\r\n', '\n').split('\n');
  final out = StringBuffer();
  for (var i = 0; i < lines.length; i++) {
    final line = lines[i];
    final match = _includePattern.firstMatch(line);
    if (match == null) {
      out.write(line);
      if (i < lines.length - 1) out.write('\n');
      continue;
    }
    final incRel = match.group(1)!.replaceAll('\\', '/');
    if (incRel.contains('..')) {
      throw FormatException(
        '$sourceRelPath:${i + 1}: #include path cannot escape $_dir: $incRel',
      );
    }
    if (!stack.add(incRel)) {
      throw FormatException(
        '$sourceRelPath:${i + 1}: circular #include detected for "$incRel"',
      );
    }
    final incFile = File('$baseDir/$incRel');
    if (!incFile.existsSync()) {
      throw FormatException(
        '$sourceRelPath:${i + 1}: missing #include target "${incFile.path}"',
      );
    }
    final resolved = resolveShaderIncludes(
      incFile.readAsStringSync(),
      incRel,
      baseDir: baseDir,
      activeStack: stack,
    );
    stack.remove(incRel);
    out.write(resolved);
    if (!resolved.endsWith('\n') && i < lines.length - 1) out.write('\n');
  }
  return out.toString();
}

String _render(Map<String, String> shaders) {
  final b = StringBuffer(_header);
  var first = true;
  for (final e in shaders.entries) {
    final f = File('$_dir/${e.key}');
    if (!f.existsSync()) {
      stderr.writeln('missing shader source: ${f.path}');
      exit(1);
    }
    var body = resolveShaderIncludes(f.readAsStringSync(), e.key);
    if (!body.endsWith('\n')) body += '\n';
    if (body.contains("'''")) {
      stderr.writeln(
        "${f.path} contains a triple quote, which cannot be embedded",
      );
      exit(1);
    }
    body = body.replaceAll(r'\', r'\\').replaceAll(r'$', r'\$');
    if (!first) b.write('\n');
    first = false;
    b.write("const String ${e.value} = '''\n$body''';\n");
  }
  return b.toString();
}

void main(List<String> args) {
  final shaders = _readManifest();
  final text = _render(shaders);
  final out = File(_out);
  final current = out.existsSync()
      ? out.readAsStringSync().replaceAll('\r\n', '\n')
      : '';
  if (args.contains('--check')) {
    if (current == text) {
      stdout.writeln('generated_shaders.dart is up to date with $_dir/');
      return;
    }
    stderr.writeln(
      '$_out is STALE relative to $_dir/ — run: dart run tools/renderer/shaders.dart',
    );
    exit(1);
  }
  if (current == text) {
    stdout.writeln(
      'generated_shaders.dart already up to date (${shaders.length} shaders)',
    );
    return;
  }
  out.writeAsStringSync(text);
  stdout.writeln('wrote $_out from ${shaders.length} files in $_dir/');
}
